    "author": "",
    "description": "中新网济南8月31日电 (记者 孙婷婷)山东锚定农业强省建设目标，将观赏鱼产业作为乡村富民特色产业、休闲渔业核心增长极重点培育，探索走出一条“产业规模化、品牌特色化、融合多元化”的创新发展道路。目前，该省观赏鱼年产量超7亿尾，年产值超20亿元(人民币，下同)，产业综合实力稳居全国前列。",
    "content": "中新网济南8月31日电 (记者 孙婷婷)山东锚定农业强省建设目标，将观赏鱼产业作为乡村富民特色产业、休闲渔业核心增长极重点培育，探索走出一条“产业规模化、品牌特色化、融合多元化”的创新发展道路。目前，该省观赏鱼年产量超7亿尾，年产值超20亿元(人民币，下同)，产业综合实力稳居全国前列。"
