    "content": "8月31日，外交部发言人郭嘉昆主持例行记者会。 路透社记者提问，据称，尼泊尔官员5月底曾与中方举行会谈，寻求同中方加强气象、降雨、河流等监测数据共享，但未建立正式机制。中方能否证实？没有建立正式机制的原因是什么？目前中方向尼泊尔分享了哪些信息？此次泥石流灾害发生前是否向尼方通报异常迹象或预警指标？后续在与尼方开展数据共享方面将采取哪些举措？ 郭嘉昆表示，中尼双方在气象、水利、防灾减灾等领域一直保持良好合作。灾害发生后，中方同尼方就人员搜救、信息共享、防止次生灾害等保持顺畅沟通，持续向尼方提供气象、水文等资料，开展专…"
