    "title": "石泰峰在学习《习近平党建文选》座谈会暨习近平党建思想研究中心成立会上强调，学好用好《习近平党建文选》，把学习成效转化为管党治党、兴党强党的生动实践",
    "link": "https://m.thepaper.cn/detail/33979057",
    "pub_date": "2026-08-31 19:49:21",
    "author": "新华社",
    "description": "学习《习近平党建文选》座谈会暨习近平党建思想研究中心成立会31日在京召开。中共中央政治局委员、中央组织部部长石泰峰出席会议并讲话，强调要学好用好《习近平党建文选》，坚持读原著学原文悟原理，深刻领悟习近平党建思想的历史逻辑、理论逻辑、实践逻辑，自觉用以指导和推进党的建设，不断把党建设得更加坚强有力。 石泰峰表示，《习近平党建文选》生动记录新时代管党治党、兴党强党伟大实践，充分反映习近平党建思想丰富内涵、科学体系、理论品格和重大原创性贡献，…",
