    "description": "中新网重庆8月31日电 (何蓬磊 梁钦卿)记者31日从重庆市城市管理局获悉，《重庆市中心城区停车设施专项规划》(以下简称《规划》)近日正式发布。作为重庆首部覆盖未来十年的停车设施专项规划，《规划》提出分阶段完善停车设施布局，至2028年推进152个公共停车场项目建设，预计新增公共停车泊位约2.4万个。",
    "content": "中新网重庆8月31日电 (何蓬磊 梁钦卿)记者31日从重庆市城市管理局获悉，《重庆市中心城区停车设施专项规划》(以下简称《规划》)近日正式发布。作为重庆首部覆盖未来十年的停车设施专项规划，《规划》提出分阶段完善停车设施布局，至2028年推进152个公共停车场项目建设，预计新增公共停车泊位约2.4万个。"
