    "content": "新华社北京8月31日电 题：抢通保供齐发力 中央企业持续增派力量驰援西藏吉隆 新华社记者戴小河、赵怡宁 西藏吉隆泥石流灾害发生后，各中央企业闻令而动、星夜驰援，人员队伍、专业装备、救灾物资持续向抢险一线集结。国务院国资委迅速作出安排，中央企业应急救援综合平台强化协调联动，专业救援力量梯次投入不断加码。截至8月31日午间，道路抢通、隐患监测、电力通信保障、民生供给等各条战线聚力攻坚，各项工作扎实有序推进。 道路抢通是当前抢险救援的首要任务。作为主攻力量，中国安能投入310人、120台装备，重点承担216国道抢通、堰塞…"
