    "description": "新华社北京8月31日电 全国政协主席王沪宁31日在京会见奥地利国民议会议长罗森克兰茨。 王沪宁表示，2018年，习近平主席同访华的范德贝伦总统共同确立中奥友好战略伙伴关系，开启两国关系新篇章。双方要以建交55周年为契机，落实两国领导人重要共识，密切高层交往，巩固政治互信，深化务实合作，加强人文交流，更好造福两国人民。中国全国政协愿同奥方加强友好交往，为深化中奥关系添砖加瓦。 罗森克兰茨表示，奥中两国都具有悠久历史和文化。建交55年来，双…",
    "content": "新华社北京8月31日电 全国政协主席王沪宁31日在京会见奥地利国民议会议长罗森克兰茨。 王沪宁表示，2018年，习近平主席同访华的范德贝伦总统共同确立中奥友好战略伙伴关系，开启两国关系新篇章。双方要以建交55周年为契机，落实两国领导人重要共识，密切高层交往，巩固政治互信，深化务实合作，加强人文交流，更好造福两国人民。中国全国政协愿同奥方加强友好交往，为深化中奥关系添砖加瓦。 罗森克兰茨表示，奥中两国都具有悠久历史和文化。建交55年来，双方坚持相互平等，两国友谊不断深化。近年来，奥中高层交往密切，这是两国关系深入发展…"
