    "description": "新华社北京8月31日电 学习《习近平党建文选》座谈会暨习近平党建思想研究中心成立会31日在京召开。中共中央政治局委员、中央组织部部长石泰峰出席会议并讲话，强调要学好用好《习近平党建文选》，坚持读原著学原文悟原理，深刻领悟习近平党建思想的历史逻辑、理论逻辑、实践逻辑，自觉用以指导和推进党的建设，不断把党建设得更加坚强有力。 石泰峰表示，《习近平党建文选》生动记录新时代管党治党、兴党强党伟大实践，充分反映习近平党建思想丰富内涵、科学体系、理…",
    "content": "新华社北京8月31日电 学习《习近平党建文选》座谈会暨习近平党建思想研究中心成立会31日在京召开。中共中央政治局委员、中央组织部部长石泰峰出席会议并讲话，强调要学好用好《习近平党建文选》，坚持读原著学原文悟原理，深刻领悟习近平党建思想的历史逻辑、理论逻辑、实践逻辑，自觉用以指导和推进党的建设，不断把党建设得更加坚强有力。 石泰峰表示，《习近平党建文选》生动记录新时代管党治党、兴党强党伟大实践，充分反映习近平党建思想丰富内涵、科学体系、理论品格和重大原创性贡献，是学习贯彻习近平党建思想的权威教材。要深刻领会把握新时代…"
