    "author": "mahui",
    "description": "双持 HarmonyOS 手机和 Mac 的人应该都有体会：华为的生态协同是给自家笔记本的， 苹果的接力是给 iPhone 的，两边都不带我们玩。手机上复制一段文字想在 Mac 上用， 最快的办法居然是发微信文件传输助手。 忍了一年之后我写了一个：灵犀互联（ Lynsi ）。两端原生（手机 ArkTS ，Mac Swift ）， 上周两边商店都过审上架了，这周刚发了 1.0.0 ，正在审核中。 它能做什么 投屏：手机画面实时到 Mac …",
