    "content": "SpaceX 猎鹰重型火箭搭载「罗曼太空望远镜」（Roman Space Telescope）发射升空，肯尼迪航天中心。8月30日，猎鹰重型火箭发射31分钟后成功将「罗曼太空望远镜」送入地日转移轨道，该望远镜已与地面建立通信连接并展开太阳能电池板，预计飞行3个月后抵达距离地球约150万公里的日地拉格朗日L2点。「罗曼太空望远镜」是 NASA 的新一代广域红外巡天望远镜，主镜口径达2.4米，配备3亿像素相机和星冕仪，视场效率达到哈勃太空望远镜的100倍以上，主要任务是探测宇宙暗物质和系外行星，目标在5年内观测至少10…"
