    "content": "2026年是中国工农红军长征胜利90周年。由中国侨联主办，福建、江西、河南等12个省级侨联承办的2026“亲情中华·中国寻根之旅”夏令营长征主题活动于5月至8月陆续举行。 云南昆明营在长征专题讲座中融入南侨机工万里归国支援祖国的故事，贵州遵义营利用VR技术还原遵义会议等历史场景，陕西营在非遗体验中引导营员感悟陕北军民的同心聚力……本次活动吸引了来自马来西亚、美国、英国、加拿大、阿联酋等22个国家的700余名海外华裔青少年参与。各省级侨联立足本土红色资源，组织营员走访长征沿线革命旧址、纪念馆，通过现场讲解、实物观览、…"
