    "content": "新华社比什凯克8月31日电（记者董雪 苟洪景）当地时间8月31日上午，国家主席习近平夫人彭丽媛在比什凯克同吉尔吉斯斯坦总统扎帕罗夫夫人扎帕罗娃参观吉尔吉斯共和国国家历史博物馆。 新华社比什凯克8月31日电（记者董雪 苟洪景）当地时间8月31日上午，国家主席习近平夫人彭丽媛在比什凯克同吉尔吉斯斯坦总统扎帕罗夫夫人扎帕罗娃参观吉尔吉斯共和国国家历史博物馆。 彭丽媛同扎帕罗娃一道欣赏热情友好的迎宾表演。随后，两国元首夫人共同参观吉尔吉斯斯坦传统文化展。彭丽媛表示，博物馆陈列的服饰、织毯等工艺精美、色彩丰富，展现出吉尔吉斯…"
