    "description": "国家统计局服务业调查中心、中国物流与采购联合会31日发布数据显示，8月份我国制造业采购经理指数（PMI）为49.8%，比上月上升0.6个百分点；非制造业商务活动指数为49.0%，与上月持平；综合PMI产出指数为49.5%，比上月上升0.2个百分点，经济总体产出景气水平有所改善。 策划：令伟家 统筹：刘雅萱 制作：闫建华",
