    "description": "9月1日起，59项强制性国家标准和375项推荐性国家标准开始实施。其中，家用电器、机器人智能控制、智能终端软件平台、电子商务等重要国家标准，将为引领相关产业高质量发展、提高产品质量、满足人民美好生活需要等提供标准支撑。 记者：赵怡宁 海报制作：赵怡宁 新华社国内部出品",
    "content": "9月1日起，59项强制性国家标准和375项推荐性国家标准开始实施。其中，家用电器、机器人智能控制、智能终端软件平台、电子商务等重要国家标准，将为引领相关产业高质量发展、提高产品质量、满足人民美好生活需要等提供标准支撑。 记者：赵怡宁 海报制作：赵怡宁 新华社国内部出品"
