    "content": "作为人工智能（AI）大模型处理信息的基本单位，词元（Token）正加速走进金融服务场景，一些银行将其作为授信参考指标之一。近段时间，多家银行的“Token贷”产品接续落地，为缺乏传统抵押物的轻资产科创企业打开了融资新空间。“Token贷”怎么贷？主要面向哪些企业？又折射出怎样的银行授信新趋势？ Token消耗量纳入授信参考指标 近期，温州金酷网络科技有限公司凭借历史词元结算数据、算力采购合同、下游业务订单及自主知识产权等，从农业银行拿到20万元贷款，资金定向用于算力采购，满足企业资金周转之需。 “随着我们自主研发的…"
