    "content": "据灯塔专业版消息，国产动画电影《牛来》今日官宣密钥延期。 影片于2026年8月5日公映，原定放映周期即将结束，现确定自9月5日起延长发行放映时间，延期至 2026年10月4日。 这意味着这部现象级动画将在院线横跨暑期与国庆两大档期，累计上映周期长达两个月。 《牛来》自上映以来，凭借“粗糙建模”引发的猎奇效应与病毒式网络传播，票房从首周不足万元一路逆袭。影片在豆瓣评分也达到了6分左右，IMDb评分6.5分，评价极度两极分化。 同时，影片在全球范围内引发“烂片文化”讨论，肯德基西班牙、荷兰铁路甚至马来西亚医院均曾主动蹭…"
