    "title": "外交部：在尼灾区取得联系的中方人员已妥善转移安置",
    "link": "http://www.news.cn/20260831/41cc19c4e6e046cc91cc283cdf790cf3/c.html",
    "pub_date": "2026-08-31 17:15:52",
